optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/identity.rs b/tools/bot-evaluation/src/identity.rs
index 1861494b..61a6b253 100644
--- a/tools/bot-evaluation/src/identity.rs
+++ b/tools/bot-evaluation/src/identity.rs
@@ -1,7 +1,14 @@
 use serde_json::Value;
 use sha2::{Digest, Sha256};
 pub fn sha(bytes: impl AsRef<[u8]>) -> String {
-    format!("{:x}", Sha256::digest(bytes))
+    let digest = Sha256::digest(bytes);
+    let mut encoded = String::with_capacity(64);
+    const HEX: &[u8; 16] = b"0123456789abcdef";
+    for byte in digest {
+        encoded.push(HEX[(byte >> 4) as usize] as char);
+        encoded.push(HEX[(byte & 15) as usize] as char);
+    }
+    encoded
 }
 /// Version 1 canonical tree: object keys sorted, scalar lexical values normalized,
 /// arrays ordered. Timing, timestamps, filesystem paths and hash fields excluded.
